/**
 * Demo seed photographs, inlined as data URIs. Person B owns this file.
 *
 * Real photos supplied for the demo, downscaled to 600x800 and inlined so they
 * ship in the bundle with no network call and no asset pipeline, and so the
 * Moment contract can keep imageUri as a plain string. WORLD badges every one
 * of these as a demo example; they are never passed off as live submissions.
 *
 * Regenerate with:
 *   sips -s format jpeg -s formatOptions 62 -Z 800 <photo> --out seed.jpg
 *   base64 -i seed.jpg
 */

export const SEED_IMAGE_HARBOUR =
  'data:image/jpeg;base64,';

export const SEED_IMAGE_CONTRAILS =
  'data:image/jpeg;base64,';

export const SEED_IMAGE_CLOUD =
  'data:image/jpeg;base64,';

